      CollectionStrings.moveBuddyBody('', 'Nguyễn Văn A', ''),
    );
    expect(
      l10n.collectionMoveBuddyBody('', 'Nguyễn Văn A', 'Nguyễn Văn A'),
      CollectionStrings.moveBuddyBody('', 'Nguyễn Văn A', 'Nguyễn Văn A'),
    );
