      l10n.collectionMoveBuddyBody('', '{value}\n!', ''),
      CollectionStrings.moveBuddyBody('', '{value}\n!', ''),
    );
    expect(
      l10n.collectionMoveBuddyBody('', '{value}\n!', 'Nguyễn Văn A'),
      CollectionStrings.moveBuddyBody('', '{value}\n!', 'Nguyễn Văn A'),
    );
